package fixture;
import org.springframework.stereotype.Service;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.transaction.annotation.EnableTransactionManagement;
import org.springframework.context.annotation.Configuration;
import org.springframework.context.annotation.Bean;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;
import org.springframework.jdbc.core.JdbcTemplate;

@Configuration
@EnableTransactionManagement(proxyTargetClass = true)
class Config {
    @Bean public DataSourceTransactionManager tx() { return new DataSourceTransactionManager(); }
}
@Service
class Operations<JdbcTemplate extends ApplicationJdbc> {
    @Autowired JdbcTemplate jdbc;
    @Transactional public void sequence() {
        jdbc.execute("SELECT * FROM accounts");
        jdbc.update("DELETE FROM ledger");
    }
}

@Service
class ApplicationJdbc {
    public void execute(String sql) { throw new IllegalStateException("application implementation"); }
    public int update(String sql) { return 0; }
}

